function construct_gsn_basis_ys_splus2(lambda, m, nu, omega)
    lambda = ComplexF64(lambda)
    m = Float64(m)
    nu = Float64(nu)
    omega = ComplexF64(omega)
    l2 = lambda * lambda
    l3 = l2 * lambda
    m2 = m * m
    m3 = m2 * m
    m4 = m3 * m
    o2 = omega * omega
    o3 = o2 * omega
    o4 = o3 * omega
    s1 = sin(nu)
    c1 = sqrt((1 - s1) * (1 + s1))
    sn = s1
    sn2 = sn * sn
    sn3 = sn2 * sn
    sn4 = sn3 * sn
    sn5 = sn4 * sn
    sn6 = sn5 * sn
    sn7 = sn6 * sn
    sn8 = sn7 * sn
    sn9 = sn8 * sn
    sn10 = sn9 * sn
    sn11 = sn10 * sn
    sn12 = sn11 * sn
    sn13 = sn12 * sn
    sn14 = sn13 * sn
    sn15 = sn14 * sn
    sn16 = sn15 * sn
    sn17 = sn16 * sn
    sn18 = sn17 * sn
    cs = sqrt(max(0.0, 1.0 - sn * sn))
    coeffs = Vector{ComplexF64}(undef, LEN_GSN_BASIS_ys_splus2)
    _construct_gsn_basis_ys_splus2_block_1!(coeffs, lambda, m, omega, l2, m2, o2, sn, sn2, sn3, sn4, sn5, sn6, sn7, sn8, sn9, sn10, cs)
